globalThis.__IT_TREND_EMBEDDED_DATA__ = {"updated_at":"2026-11-25 02:15:49 JST","total_count":50,"config":{"selected_genres":["ai","web","infra","mobile","biz"],"other_genre_min_ratio":0.25,"max_age_hours":72.0,"genres":{"ai":"AI・LLM・機械学習","web":"Web開発・言語","infra":"インフラ・クラウド・セキュリティ","mobile":"モバイル・ガジェット・個人開発","biz":"ITビジネス・キャリア・マネジメント","other":"総合・その他IT"}},"articles":[{"title":"当社お客様の情報漏えいに関するお詫びとお知らせ（第2報）:楽天証券","url":"https://www.rakuten-sec.co.jp/web/info/info20261124-04.html","source":"Hatena","published_at":"2026-11-24 22:06","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"2026年11月17日（火）にお知らせした、「楽天証券のお客様の情報漏えいの可能性に関するお詫びとお知らせ」（以下「第1報」）について…","summary":"ご不便をおかけし申し訳ございません。当社お客様の情報漏えいに関するお詫びとお知らせ（第2報） 2026年11月17日（火）にお知らせした、「楽天証券のお客様の情報漏えいの可能性に関するお詫びとお知らせ」（以下「第1報」）について、これまでの調査で判明した事実について、お知らせいたします。\n\n外部に持ち出された情報について（第2報） 部店・お客様コード、ログインID ※1 に加え，氏名、カナ氏名、生年月日、住所、電話番号などのお客様の個人情報の漏えいは約441万件 ※2 であることがわかりました。そのうち、約322万口座は口座をお持ちのお客様の情報、約119万件 ※2 は口座未開設の方の情報 ※3 となります。\n\nなお、商品別資産情報 ※4 は約168万件、お客様ご申告の年収情報は約1.4万件、お客様ご申告の資産情報は約271万件でした。年収と資産情報については、お客様の自己申告情報、かつ、選択した番号のみ（詳細な金額情報は含まない）の情報となります。","importance":5},{"title":"ソフトバンク、アイティメディアの売却検討か　2社「コメント控える」「決定した事実ない」","url":"https://www.itmedia.co.jp/news/article/2611/24/2000003427/","source":"Hatena","published_at":"2026-11-24 21:28","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"ソフトバンクは11月24日、傘下のアイティメディア（東京都千代田区）の売却を検討しているとする日本経済新聞の報道について、ITmedi…","summary":"ソフトバンクは11月24日、傘下のアイティメディア（東京都千代田区）の売却を検討しているとする日本経済新聞の報道について、ITmedia NEWSの取材に対し「当社が発表したものではないため、コメントを控える」と回答した。ITmedia NEWSの取材に対し、ソフトバンクは「コメントを控える」、アイティメディアは「現時点で決定した事実はない」と回答した。\n\nアイティメディア広報も「当社が発表したものではない」とした上で、「現時点で決定した事実はない」としている。報道によると、ソフトバンクは株式の売却に向け、みずほ証券をアドバイザーに起用し、準備を進めているという。\n\n非中核事業を切り離し、AI関連事業に経営資源を集中させる狙いがあるとしている。ソフトバンクは9月末時点で、完全子会社のSBメディアホールディングスを通じ、アイティメディア株式の52.98％を保有している。\n\nアイティメディアは1999年設立。","importance":5},{"title":"Chrome版「LINE」、2027年1月26日に終了","url":"https://k-tai.watch.impress.co.jp/docs/news/2158838.html","source":"Hatena","published_at":"2026-11-24 21:13","genre":"mobile","genre_label":"モバイル・ガジェット・個人開発","headline":"2026年11月24日 18:17 LINEヤフーは24日、Chrome版およびWhale版LINEの提供を2027年1月26日に終了…","summary":"2026年11月24日 18:17 LINEヤフーは24日、Chrome版およびWhale版LINEの提供を2027年1月26日に終了すると発表した。LINEサービスの運営方針の見直しの一環としている。\n\n引き続きサブ端末として利用する場合、スマートフォン版LINE（Android）、PC版LINE（Windows／Mac）、またはタブレット版LINE（iPad／Androidタブレット）をダウンロードして利用する必要がある。Chrome版LINEは当初2025年9月22日にサポート終了予定だったが、2026年上半期に延期されていた。\n\n同社では、サービス終了にあたって個人情報やログイン情報などの入力を求めたり、他のサービスの利用を勧めたりすることは一切ないとしており、サービス終了に便乗した不審な連絡や案内には十分注意するよう呼びかけている。","importance":5},{"title":"都営新宿線「岩本町駅」が急行停車駅に　秋葉原との乗換駅","url":"https://www.watch.impress.co.jp/docs/news/2158833.html","source":"Hatena","published_at":"2026-11-24 21:12","genre":"other","genre_label":"総合・その他IT","headline":"2026年11月24日 18:15 都営地下鉄新宿線の急行が、3月13日から「岩本町駅」に停車するようになる。","summary":"2026年11月24日 18:15 都営地下鉄新宿線の急行が、3月13日から「岩本町駅」に停車するようになる。岩本町駅はJR等の秋葉原駅との乗換駅となっている。\n\n3月13日はダイヤ改正日で、始発から運用を開始する。あわせて、一部の各駅停車を急行に変更して急行の運転本数を増やす。\n\nまた、急行が岩本町駅と大島駅で、それぞれ各駅停車と接続する。岩本町駅は急行と各駅停車が同じホームから乗車でき、スムーズに乗り換えができるとしている。","importance":5},{"title":"Ruby で学ぶ Windows システムプログラミング","url":"https://www.hsbt.org/slide/20261121-SendaiRubyKaigi03/","source":"Hatena","published_at":"2026-11-24 16:39","genre":"web","genre_label":"Web開発・言語","headline":"仙台Ruby会議03 / 2026年11月","summary":"Ruby で学ぶ Windows システムプログラミング。仙台Ruby会議03 / 2026年11月","importance":5},{"title":"ソフトウェアファクトリーを前提に、サービス開発はどう変わるか｜すてぃお","url":"https://note.com/suthio/n/n91e27ebb133d","source":"Hatena","published_at":"2026-11-24 13:30","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"前提DORAの2025年レポートは、AIはチームにもともとある強みと弱みを増幅すると報告しています。","summary":"前提DORAの2025年レポートは、AIはチームにもともとある強みと弱みを増幅すると報告しています。Faros AIの調査でも、AIの利用が進むチームでは、マージされるPRが増える一方、レビュー時間も長くなっていました。\n\nDORAレポートの2025年版が出た。AIは増幅器であり、組織の能力を映す鏡。\n\n一方、規模が大きくなると、僕が見てきた限りでは、書く量だけ増えてレビューが渋滞するか、見たふりをして品質を犠牲にしながら流すか、のどちらかに寄りやすくなります。AIにもっと仕事を任せるには、まず成果を検証しやすくする必要があります 製造業などの機械化とLauren Tanさんの講演を手がかりに、検証からリリースまでをどう組み立てるか考えてみます。\n\nFaros AI Claude CodeやCodexを使うと、個人開発や小さな案件では、以前よりずっと速く実装できます。DORAの2025年レポート は、AIはチームにもともとある強みと弱みを増幅すると報告しています。\n\n高パフォーマンス組織の強みを増幅し、より速く革新的にする。","importance":5},{"title":"来たる「Windows Server 2028」は既定で32bitアプリを実行できない！ 「WoW64」が削除／必要ならオンデマンド機能として追加可能、マルウェア対策の一環【やじうまの杜】","url":"https://forest.watch.impress.co.jp/docs/serial/yajiuma/2158861.html","source":"Hatena","published_at":"2026-11-24 21:43","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"必要ならオンデマンド機能として追加可能、マルウェア対策の一環 2026年11月24日 06:45 「やじうまの杜」では、ニュース・レビ…","summary":"必要ならオンデマンド機能として追加可能、マルウェア対策の一環 2026年11月24日 06:45 「やじうまの杜」では、ニュース・レビューにこだわらない幅広い話題をお伝えします。次期サーバーOS 「Windows Server 2028」では、32bitアプリの実行に必要な「WoW64」が既定でアンインストールされる とのこと。\n\n米Microsoftがテクニカルカンファレンス 「Ignite 2026」 のセッションで明らかにしています。動画は「YouTube」で視聴可能。\n\n「Windows Server 2028」では、従来の “互換性重視” から “初期状態で安全”（Secure by Default） へと、セキュリティ方針が大きく転換されました。これに伴い、 「Windows PowerShell 5.1」「WDS」が非推奨になるほか、「WSUS」や「SMB 1.0」、「VBScript」などが削除される予定 です。","importance":5},{"title":"1台数億円するのに 手術支援ロボットが使われない | NHKニュース","url":"https://news.web.nhk/newsweb/na/nd-20261120de78959","source":"Hatena","published_at":"2026-11-24 20:45","genre":"other","genre_label":"総合・その他IT","headline":"手術をより安全にできるとして急速に普及している手術支援ロボット。","summary":"1台数億円するのに 手術支援ロボットが使われない | NHKニュース。手術をより安全にできるとして急速に普及している手術支援ロボット。\n\n1台数億円しますが、国内には1000台以上導入されていて人口あたりの台数はアメリカに次いで2番目に多くなっています。","importance":5},{"title":"Copilot Studioのエージェント開発をClaude Codeにどこまで任せられるか試した","url":"https://zenn.dev/upgradetech/articles/a9a1637d3071c1","source":"Zenn","published_at":"2026-11-24 18:24","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"Copilot Studioのエージェントを画面操作で作っていて、直すたびにどこを変えたのか分からなくなっている方 Claude Co…","summary":"Copilot Studioのエージェントを画面操作で作っていて、直すたびにどこを変えたのか分からなくなっている方 Claude Codeを使い始めて、コードを書く以外の仕事にも使えないか考えている方 「AIにアプリを作らせる」が実際どこまで通用するのか、判断材料がほしいPM・マネージャーの方 記事を見ながら同じものを自分の環境で作ってみたい方 この記事を読むと、小さなサンプルでClaude Codeにどこまで任せられたのかが分かります。\n\n同じものを自分の環境で作る手順も載せています。1.\n\nCopilot Studioのエージェント作りをClaude Codeに頼んでみた Copilot Studioはエージェント（会話に答えたり作業をこなしたりするAIアシスタント）を主に画面操作で作れるMicrosoftのサービスです。ふだんはブラウザでCopilot Studioを開き、エージェントへの指示や会話の内容を画面に入力して作っていきます。","importance":5},{"title":"あなたの「信用情報」をスマホで確認できるサービス、JICCが再開","url":"https://japan.cnet.com/article/35255340/","source":"Hatena","published_at":"2026-11-24 18:16","genre":"mobile","genre_label":"モバイル・ガジェット・個人開発","headline":"日本信用情報機構（JICC）は11月24日、利用者が自分の信用情報を取り寄せられるスマートフォンアプリのサービスを再開したと発表した。","summary":"日本信用情報機構（JICC）は11月24日、利用者が自分の信用情報を取り寄せられるスマートフォンアプリのサービスを再開したと発表した。","importance":5},{"title":"「昨日ゲーセンで千円と自販機で150円」を家計簿の2行にする ― Apps Script で日本語の金額・日付を読む","url":"https://zenn.dev/moneystock/articles/gas-kakeibo-japanese-amount-parser","source":"Zenn","published_at":"2026-11-24 16:29","genre":"web","genre_label":"Web開発・言語","headline":"Google スプレッドシートと Apps Script で家計簿を作っています。","summary":"Google スプレッドシートと Apps Script で家計簿を作っています。レシートの写真は Gemini API に読ませますが、自販機やゲームセンターのように レシートが出ない支出 は、スマホから文字で入れます。\n\nこれを、次の2行にするのが目標です。全部を LLM に投げれば済みそうですが、そうしませんでした。\n\n理由は3つです。遅い 。\n\nApps Script から Gemini を呼ぶと、返事まで数秒〜数十秒かかります。「ゲーセン 1000」と打つたびに待つのは続きません。\n\n止まる 。無料枠の上限や混雑(429・503)のときに、記録そのものができなくなります。\n\nほとんどは規則で読める 。家計簿に入れる文は短く、形が決まっています。\n\nそこで、 まず正規表現と辞書で読み、自信がないときだけ Gemini に聞く 形にしました。この記事は、その「規則で読む」側の実装と、はまった所の記録です。\n\nコードは Apps Script(V8)でも node でも動く、ただの JavaScript です。","importance":5},{"title":"女子中学生が発明した「海底のゴミ箱」、マイクロプラの96%を生まれる前に食い止める | ギズモード・ジャパン","url":"https://www.gizmodo.jp/article/2611-underwater-trash-can-microplastics/","source":"Hatena","published_at":"2026-11-24 13:24","genre":"other","genre_label":"総合・その他IT","headline":"海の底にゴミ箱。","summary":"海の底にゴミ箱。ハンガリーの女子中学生、ラウラ・イヴァーンカさんが考えた「DIVE&CLEAN」が「ストックホルム青少年水大賞2026」で、審査員特別賞を受けました。\n\n本人のモデルによる試算では、マイクロプラスチックの96%を、生まれる前に食い止められるといいます。ラウラさんは8歳からのダイバー。\n\nダイバーが手軽にプラごみを回収し、マイクロプラスチックの流出を防ぐ仕組みです。拾いたいのに、捨てる場所がない ラウラさんは8歳からのダイバー。\n\n家族旅行で何度も潜ったマルタの海で、ゴミが海底にたまっていくのを見てきたそうです。拾いたい。\n\nでも、水中には捨てる場所がない。これ、街なかでも覚えがありません？\n\n空のペットボトルの捨て場所がなくて、カバンに入れたまま持ち帰るアレです。かといってポイ捨てするのはだめですけどね。\n\nゴミ箱がないなら、沈めればいいじゃない そこでラウラさんが考えたのが、 ダイビングのルート沿いの海底に、固定式の回収ボックスを置く 仕組み。ダイバーは潜るついでにプラごみを拾って、箱にポイッ。\n\nそれだけです。","importance":5},{"title":"エヌビディア株、31％急騰　時価総額151兆円増","url":"https://www.cnn.co.jp/business/35255312.html","source":"Hatena","published_at":"2026-11-24 09:42","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"23日、米半導体大手エヌビディアの株価が30％を超える値上がりを記録した/Spencer Platt/Getty Images （CN…","summary":"23日、米半導体大手エヌビディアの株価が30％を超える値上がりを記録した/Spencer Platt/Getty Images （CNN） 米半導体大手エヌビディアの株価は23日、同社がジェンスン・フアン氏を最高経営責任者（CEO）兼社長に即日復帰させたと発表したことを受け、30％超急騰した。\n\n1日の上昇率としては過去3番目の大きさだった。エヌビディア株は一時36.6％高となり、その後やや上げ幅を縮めて31.48％高で取引を終えた。\n\n上昇率は2003年以来の大きさで、時価総額は1日で9520億ドル（約151兆円）増加した。GDSウェルス・マネジメントのグレン・スミス最高投資責任者（CIO）は「ジェンスン・フアン氏をCEOに復帰させるという衝撃的な決定は、ここ数週間低迷していたAI（人工知能）関連株にとって、大きな不透明要因の解消につながる」とメモに記した。\n\nこの発表を受け、すでに堅調だった米株式市場は一段高となった。ハイテク株中心のナスダック総合指数は6.51％急伸。","importance":5},{"title":"自宅DNSサーバを遠隔で再起動したら45分戻らず、家のネットが止まった話","url":"https://zenn.dev/yowahada/articles/wyse-remote-reboot-hang","source":"Zenn","published_at":"2026-11-24 18:28","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"前編 と 後編 では、余っていた小型PC（Dell Wyse 3040）にAdGuardHomeを入れて、家のDNSサーバにしました。","summary":"前編 と 後編 では、余っていた小型PC（Dell Wyse 3040）にAdGuardHomeを入れて、家のDNSサーバにしました。今回はその続きで、失敗の話です。\n\nカーネルの更新を当てるために、機体には触らずSSHでWyseを再起動しました。すると約45分、Wyseは戻ってきませんでした。\n\nそのあいだ、DNSをWyseだけに向けていたスマホとMacは、名前を引けなくなりました。先に結論を書いておきます。\n\nOSは正常に終了していた。そのあと機体が応答しなくなり、止まった原因は特定できていない DNSに予備がない端末は、DNSサーバが止まるとネットごと使えなくなる 遠隔で再起動する前に、「戻らなかったらどうするか」を決めておくべきだった きっかけは、脆弱性の見張りを足したことでした。\n\n家の機械のソフトが古くなっていないかを調べていくと、Wyseは修正済みのカーネルを入れたまま、9週間再起動していませんでした。動いていたのは、古いほうのカーネルです。","importance":5},{"title":"JSConf JP 2026 参加ログ","url":"https://zenn.dev/aishift/articles/b6dbe1c0acc505","source":"Zenn","published_at":"2026-11-24 17:53","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"こんにちは☀️ 株式会社AI Shiftでフロントエンドエンジニアをしているさっちゃんです！","summary":"こんにちは☀️ 株式会社AI Shiftでフロントエンドエンジニアをしているさっちゃんです！（X： おさわ / 吉岡 爽 ） 2026年11月22日（日）にベルサール神田で開催された JSConf JP 2026 に参加してきました！\n\n4トラック並行で、キーノートは Brendan Eich さんへのインタビューと Josh Junon さんの講演の2本でした。https://jsconf.jp/2026/ この記事は、自分が聞いたセッションのメモを時系列でまとめた参加ログです。\n\nスライドが公開されているものは埋め込みました。内容は自分のメモとスライドをもとに整理したもので、聞き違いがあればご指摘ください🙏 1日を通して個人的に強く印象に残ったテーマは3つでした。\n\nサプライチェーン攻撃 ：npm のサプライチェーン攻撃を扱うセッションが朝から夜まで続き、締めのキーノートは chalk / debug を乗っ取られた当事者の方のお話でした。共通していたのは 「銀の弾丸はない、多層で備える」 というメッセージでした。","importance":5},{"title":"カップヌードルミュージアムに行った報告をXにアップしたら12時間ロック、「合意のない裸の描写を禁止するルールに違反しています」とのこと…「ヌード」ルがダメらしい","url":"https://togetter.com/li/2774298","source":"Hatena","published_at":"2026-11-24 11:51","genre":"other","genre_label":"総合・その他IT","headline":"KATSU @disney_jack 昨日、カップ◯ードルミュージアムに行った報告をアップしたら、Xの運営から12時間ロックされました…","summary":"？","importance":5},{"title":"デジタル缶バッジでTHINKLETの視野を確認する","url":"https://zenn.dev/fairydevices/articles/4f842af5926a21","source":"Zenn","published_at":"2026-11-24 17:35","genre":"mobile","genre_label":"モバイル・ガジェット・個人開発","headline":"入社以来、THINKLETに表示画面がなく、現場でのアプリ操作やカメラ視野の確認ができないという課題に立ち向かってきました。","summary":"入社以来、THINKLETに表示画面がなく、現場でのアプリ操作やカメラ視野の確認ができないという課題に立ち向かってきました。古くはTHINKLET Viewerとその小型版、USBマイコンのボタンでUSBIDを使ったアプリ切り替え、音声指示でのライト制御、Tab5超うすっぺらいViewer、超小型USBディスプレイでのカメラ画像リアルタイム表示など実装を行なってきました。\n\nしかし、いずれも社内のウケがイマイチでした。THINKLET Viewerだけは、何台か制作し、営業活動などには使っていただけましたが、それも最近はあまり使われていないようですw 最新作がこちらです。\n\nまずは、ご笑覧ください。https://www.youtube.com/watch?v=uZ6x2jWOJt0 https://www.youtube.com/watch?v=Jb4NzuieMuY デモは、THINKLETにUSB接続したマイコンから指示を送ると、THINKLETのカメラ映像を取得してデジタル缶バッジに表示するものです。","importance":5},{"title":"アップグレードで消えた暗黙の契約 ― Prisma 7 と DATE 列","url":"https://zenn.dev/jins/articles/413543b799a674","source":"Zenn","published_at":"2026-11-24 15:01","genre":"web","genre_label":"Web開発・言語","headline":"0. 前置き（ほぼ愚痴です） 最近は、脆弱性の通知が本当に増えました。","summary":"0. 前置き（ほぼ愚痴です） 最近は、脆弱性の通知が本当に増えました。AI のおかげで見つけやすくなったのでしょう（あくまで個人の体感です）。\n\n検知してもらえるのはありがたいのですが、そのぶん対応も毎週のように来ます。またかと思いながら、メジャーバージョンごと入れる日もあります。\n\n今回の話は、そんな対応の 1 つから始まりました。愚痴はここまでにして、本題に入ります。\n\n1. 症状：エラーは出ない。ただ 0 件になる 私が扱っているのは、Node.js + Express + Prisma + PostgreSQL で作った Web アプリのバックエンドです。\n\n一覧画面から、日付の範囲で検索できます。前置きで愚痴ったとおり、脆弱性対応の一環として Prisma 6 から 7 に上げた後、次の報告が届きました。\n\n開始日と終了日を同じ日にして検索すると、0 件になる 調べると、同日指定だけの問題ではありませんでした。範囲の 終了日が、必ず結果から落ちて いました。\n\n同日指定は、開始日と終了日が同じなので、結果が空になるだけです。","importance":5},{"title":"パスワード、全く自己管理する気がなくほぼ毎回リセットする運用の人が居てびびった→実はむしろこれが正しい運用であることをまだ人類は知らない","url":"https://togetter.com/li/2774455","source":"Hatena","published_at":"2026-11-24 18:12","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"公開 2026年11月24日17:50 （8時間前） 話題 安全性 社会 セキュリティ パスワード パスワード、全く自己管理する気がな…","summary":"公開 2026年11月24日17:50 （8時間前） 話題 安全性 社会 セキュリティ パスワード パスワード、全く自己管理する気がなくほぼ毎回パスワード忘れたからメール経由でリセットする運用の人が居てびびった 毎回パスワードリセットしてるけど、これってダメなの…？\n\nこれってなんかダメなの？統一すると危険だし、かと言ってバラバラのパスワード覚え切れないしメモに残すのも危ないから利用頻度の高くないパスワードは全部この運用にしてるんだけど、もしかしてまずい？\n\n自動生成パスワード使って毎回リセットしてる。一年か半年に一度くらいしかアクセスしないサイトでやられると、そんなもの覚えてねえよ！\n\nとなる。全部スマホSMS認証でいいじゃんよ。\n\nひと手間あるものの、パスワードよりSMS認証のほうが優れている。ここで言いたいことは「覚えられるパスワードなんか使うな」ってことであってEメール認証が安全とは言ってない。\n\nただ人間が覚えられるパスワードなんかを使うよりはマシってことを言いたかった。！\n\n忘れちゃうから毎回パスワード申請してたの良かったのか！","importance":5},{"title":"提供中のHP用に簡単なCMSを作ってみた","url":"https://zenn.dev/billysama/articles/4a7202a34d3466","source":"Zenn","published_at":"2026-11-23 23:10","genre":"other","genre_label":"総合・その他IT","headline":"自社でHPを制作・提供しています。","summary":"自社でHPを制作・提供しています。ニュースを更新するたびにサイトのコードを直し、再デプロイするのは手間でした。\n\nそこで、複数のHPの記事を一つの画面で管理できるCMSを作りました。記事の作成・公開はCMSで行い、表示は各HPが担います。\n\nまず自社HPにつなぎ、別のデザインでも使えるか確かめるため、カフェのサンプルサイトにも接続しました。作ったCMSの記事一覧。\n\n自社HPの確認用記事を下書きとして保存している。CMSを選ぶときはmicroCMSも検討しました。\n\n料金表 を見ると、無料のHobbyプランはメンバーが最大3名で、プランはサービスごとの契約です。顧客にもニュースを編集してもらい、複数のHPを扱う当社の想定では、Hobbyの枠に収まりにくく、Team以上の費用を見込むことになります。\n\n顧客ごとに編集できる範囲を細かく分ける権限管理はBusinessプランの機能です。今の当社の規模では、この固定費を負担し続けるのは難しいと考えました。\n\nもう一つは編集する人の使いやすさです。","importance":5},{"title":"設計書のないClassic ASP アプリを ASP.NET Core にマイグレーションしたときにやったこと","url":"https://zenn.dev/pomio/articles/2026-11-22_mig","source":"Zenn","published_at":"2026-11-24 17:51","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"Classic ASP で書かれた約10万ステップのシステムを、C# の ASP.NET Core にマイグレーションする案件に参画し…","summary":"Classic ASP で書かれた約10万ステップのシステムを、C# の ASP.NET Core にマイグレーションする案件に参画しました。参画した当初の状態としては、アプリの設計書は一切なく、ASP.NET Core や MVC に知見のある開発者もチームにいない状態でした。\n\nここから一人で移行の計画～テストまでを担当することになりました。この記事では、そんな案件でコードを書き始める前に決めたことと、その理由を、備忘録も兼ねて書いていきます。\n\n移行元： Classic ASP 移行先： C# / ASP.NET Core 体制:：メンバーは自分含め5人（基本は3人で稼働） スケジュール:：参画後の約1年後にリリース 使えた生成AI：LightBlueという法人向けのAIアシスタント その他：マイグレーションのついでに複数の追加要件有 1.やらないことを決める まず、規模と体制が要求スケジュールに見合っていないのが明らかだったため、とにかく完成させることを目的として、やらないことを決めました。\n\n最も優先すべきは納期です。","importance":5},{"title":"iOSエンジニアのための OAuth 2.0 + PKCE 入門 ― 仕組みを理解してから、Swiftで実装する","url":"https://zenn.dev/mobile_app_tec/articles/ios-oauth2-pkce-native-app","source":"Zenn","published_at":"2026-11-23 22:56","genre":"mobile","genre_label":"モバイル・ガジェット・個人開発","headline":"業務で担当した iOS アプリ（SwiftUI）で、OAuth 2.0 + PKCE のログインを外部ライブラリなしで実装しました。","summary":"業務で担当した iOS アプリ（SwiftUI）で、OAuth 2.0 + PKCE のログインを外部ライブラリなしで実装しました。実装してみて、iOS エンジニアの間では 仕組みの理解があいまいなまま になりがちだと感じました。\n\nたとえば、次の質問にすぐ答えられるでしょうか。OAuth はログイン（認証）の仕組み？\n\nトークン交換は何分おきにするもの？PKCE は OAuth とは別のフロー？\n\nstate があれば PKCE はいらない？client_secret は難読化してアプリに埋め込めば大丈夫？\n\n第1部を読めば、これらに答えられるようになります。第1部で仕組みを、第2部で iOS での実装を説明します。\n\n1.OAuth 2.0 以前の問題 以前は、アプリが ID とパスワードを受け取り、そのままサーバーに送る方式（Resource Owner Password Credentials。\n\n以下 ROPC）がよく使われていました。","importance":5},{"title":"定番の日本語フォント「M+ FONTS」に新しい一員、「M PLUS 3」がリリース／伝統的なゴシック体の形をモダンな手法でリデザイン、「SIL OFL」で無償利用可","url":"https://forest.watch.impress.co.jp/docs/news/2158533.html","source":"Hatena","published_at":"2026-11-24 14:38","genre":"web","genre_label":"Web開発・言語","headline":"伝統的なゴシック体の形をモダンな手法でリデザイン、「SIL OFL」で無償利用可 2026年11月24日 13:57 日本語フォント「…","summary":"伝統的なゴシック体の形をモダンな手法でリデザイン、「SIL OFL」で無償利用可 2026年11月24日 13:57 日本語フォント「M PLUS 3」の公開が11月23日（日本時間）、発表された。フォントファイルは「GitHub」から入手できる。\n\n「M PLUS 1」「M PLUS 2」に続く「M+ FONTS」の新しいファミリーで、伝統的なゴシック体の形をモダンゴシックの手法でリデザインしたものという。M PLUS 3 日本語フォントを公開します。\n\n伝統的なゴシック体の形をモダンゴシックの手法でリデザインしました。","importance":5},{"title":"中古PCにProxmox VE 9.2を導入して個人開発用Staging環境を構築した記録","url":"https://zenn.dev/locu/articles/d71e8c4996a365","source":"Zenn","published_at":"2026-11-24 14:17","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"個人開発している VRC World Shelf（VRCWS） で、外部の方に開発中の画面を確認してもらう必要が出てきました。","summary":"個人開発している VRC World Shelf（VRCWS） で、外部の方に開発中の画面を確認してもらう必要が出てきました。それまではローカル開発環境と本番環境が中心で、「本番に出す前の状態を、第三者に継続して触ってもらう」ための場所がありませんでした。\n\nそこで中古PCを1台用意し、 Proxmox VE 9.2 + Debian 13 の仮想マシン でStaging環境を構築しました。この記事は2026年11月に実際に行った作業の記録です。\n\nインストール手順だけでなく、事前検証、VLANの切り替え、SSH、デプロイまでの流れと、引っかかった点を残します。まず、最終的な構成です。\n\nWebはCloudflare Workers側に配置し、 Proxmox上のVMにはAPIと依存サービス を置いています。Gitea ActionsのStaging用ワークフローも、APIの配備を担当します。\n\nWebやブラウザ拡張機能は別途検証する構成です。なぜProxmoxにしたのか 最初は単純なDebianサーバーやk3sも考えました。","importance":5},{"title":"Gemini 4 Neon を API で叩いて Claude Code・Codex CLI と比べた：65万トークンの超長文、費用、失敗","url":"https://zenn.dev/canly/articles/40e773759da8f8","source":"Zenn","published_at":"2026-11-24 17:51","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"カンリーCAIOの萩野 です。","summary":"カンリーCAIOの萩野 です。2026年11月18日に Google が出した Gemini 4 Neon を、同じ8つの課題で Claude Opus 5.5（Claude Code 経由）と GPT-6.2 Sol（Codex CLI 経由）と比べました。\n\n一般向けのまとめは note に書いたので、この記事ではどんなリクエストを送り、どう採点し、いくらかかり、どこで失敗したかを、手順を追える粒度で書きます。プロンプトの全文と正解データの作り方は付録に載せました。\n\n正解が決まる課題（数学・論理、グラフ読み取り、17万トークンの文書検索、8万トークンのグラフ探索、39万・65万トークンの超長文検索）は、実行できたものは3モデルとも満点でした。各課題1回ずつの実行で、正答率に差はつきませんでした。\n\n39万・65万トークンの超長文は、Neon（23.2s / 29.8s、$1.19 / $1.99）と Opus（26.6s / 40.1s）がどちらも7/7でした。","importance":5},{"title":"「松屋」の一人負けなのか？「吉野家」「すき家」と明暗を分けた既存店売上、その差はどこにあるのか #エキスパートトピ（三輪大輔） - エキスパート - Yahoo!ニュース","url":"https://news.yahoo.co.jp/expert/articles/c6b02eabde817393055dacbd810b748a6637ae39","source":"Hatena","published_at":"2026-11-24 12:38","genre":"web","genre_label":"Web開発・言語","headline":"既存店売上の伸び悩みが課題となっている「松屋」。","summary":"既存店売上の伸び悩みが課題となっている「松屋」。10月には牛めしを値上げし、収益性の改善を図っている（筆者撮影） 最初に断っておきたい。\n\n牛丼チェーンのなかで、私が最もよく利用するのは「松屋」である。その松屋の業績が気になっている。\n\n松屋フーズホールディングスが11月13日に発表した中間決算は、売上高が前年同期比16.7％増加した一方、営業利益は34.3％減少した。六厘舎などを展開する松富士の買収も売上を押し上げたが、利益は減った。\n\nさらに10月の既存店売上高は1.9％増、客単価は1.2％減。吉野家とすき家が客単価を伸ばす中、松屋は前年割れが続く。\n\nなぜ増収でも利益を確保できないのか。","importance":5},{"title":"Linuxでゲームが動くことと、好きなLinuxでゲームができることは違った","url":"https://zenn.dev/kuroikotech/articles/linux-gaming-custom-kernel-freedom","source":"Zenn","published_at":"2026-11-24 05:31","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"CachyOSのアップデートで、Easy Anti-Cheat Linux v2への対応が入ったらしい。","summary":"CachyOSのアップデートで、Easy Anti-Cheat Linux v2への対応が入ったらしい。2026年11月22日のリリース告知を読むと、専用カーネルの linux-cachyos-eac や、環境を準備する eac-setup が追加されていた。\n\n[1] 普段CachyOSを使っているので気になった。最初は「お、Linuxで遊べるゲームが増える方向に進んでるのか」と思ったんだけど、仕組みを追っていくうちに、少し別のことが引っかかった。\n\nゲーム用に、自分でカーネルを最適化してビルドした場合はどうなるんだろう。自分でいじったカーネルではだめなのか Epicの説明では、EAC Linux v2は、信頼された鍵で署名されたカーネルとカーネルモジュールを要求する。\n\nSecure BootやTPMによる起動の検証に加えて、rootによるカーネルの改変を制限するlockdownなども使う。[2] つまり、自分で変更してビルドしたカーネルを、自分の鍵で署名しただけでは、その鍵がEACの信頼対象になるわけではない。","importance":5},{"title":"ソフトバンク、「ITmedia」運営会社の売却検討　AI関連事業に集中 - 日本経済新聞","url":"https://www.nikkei.com/article/DGXZQOUC1688U0W6A111C2000000/","source":"Hatena","published_at":"2026-11-24 17:42","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"ソフトバンクがニュースサイト「ITmedia」などを運営するアイティメディアの売却を検討していることがわかった。","summary":"ソフトバンクがニュースサイト「ITmedia」などを運営するアイティメディアの売却を検討していることがわかった。ソフトバンクは通信から人工知能（AI）の会社へと転換を目指している。\n\n非中核事業を切り離しAI関連に経営資源を集中させる。ソフトバンクは完全子会社のSBメディアホールディングスを通じ、9月末時点でアイティメディア株式の52.98%を保有する。\n\n登録すると続きをお読みいただけます。すべての記事が読み放題 有料会員が初回1カ月無料 有料登録すると続きをお読みいただけます。\n\n無料登録でも記事消費（一定数限定）をすることで閲覧できます。","importance":5},{"title":"ゲームボーイアドバンスエミュレータをRustで書いた","url":"https://bokuweb.github.io/undefined/articles/20261103.html","source":"Hatena","published_at":"2026-11-24 11:34","genre":"web","genre_label":"Web開発・言語","headline":"ゲームボーイアドバンスエミュレータをRustで書いた #2026-11-24 ファミコン、ゲームボーイと書いてきたので次はゲームボーイ…","summary":"ゲームボーイアドバンスエミュレータをRustで書いた #2026-11-24 ファミコン、ゲームボーイと書いてきたので次はゲームボーイアドバンス（以下GBA）だろうということで（コミットログを見るに）2018年頃書き始めた。途中何度も放置しつつ、気づけば8年くらい経ってしまったが、最後はAIの力も借りつつそこそこ動くようになったので公開することにした。\n\nファミコンとゲームボーイはCPUが8bitだったが、GBAは32bitのARM7TDMIになる。今回は主にこのARM7TDMIの話を書きたいと思う。\n\nというのもGBAのエミュレータを書いていて一番時間を溶かしたのは間違いなくCPUで、描画やサウンドはそれに比べるとかなりすんなりいった。ブラウザでも動くようにしてあるので以下から試せる。\n\nデバッガも用意していて、逆アセンブル、ブレークポイント、レジスタやメモリの表示などができる。https://bokuweb.github.io/rgba/ 自由に配布できるhomebrewを40本ほど同梱している（ほかにテストROMも7本）。","importance":5},{"title":"S3 Vectors は RAG のベクトルストアに使えるか（40問で検証＋ハイブリッド検索に関する追記）","url":"https://zenn.dev/shino_i/articles/faeef70f08124c","source":"Zenn","published_at":"2026-11-24 00:57","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"JAWS-UG 神戸「残暑！","summary":"JAWS-UG 神戸「残暑！LT会」（2026-10-23）で話した内容と、その後 S3 Vectors がハイブリッド検索に対応した（2026-11-16）ことを受けた追試の結果をまとめます。\n\nなぜこのテーマにしたのか Amazon Bedrock Knowledge Bases（以下 KB）では、ベクトルストアとして Amazon OpenSearch Serverless、Amazon Aurora PostgreSQL、Amazon S3 Vectors などを選べます。\n\nこのうち OpenSearch Serverless を、社内向けやプライベートで利用するAWSアカウント上でのアプリケーション構築時など検索がそれほど多くない RAG に使う場合、私は次の2点が課題だと考えました。検索していない時間も料金がかかる ：OpenSearch Serverless の Classic 世代のコレクションでは、検索していない時間も 1 OCU（検索 0.5＋インデックス 0.5）が残りました（今回の実測）。","importance":5},{"title":"AIにイラレを触らせてみた ― バナーのサイズ違い展開を、手作業とAIで比べてみた","url":"https://zenn.dev/interpark/articles/8061229c8a5b8c","source":"Zenn","published_at":"2026-11-24 17:09","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"私はWebデザイナーをしています。","summary":"私はWebデザイナーをしています。日々のバナー制作で、地味に時間がかかっているのが サイズ違いの展開 （リサイズ）です。\n\n1枚のバナーを作ったあと、SNS用、広告用などに何サイズも作り直します。作業自体は単純ですが、サイズが変わると「どの要素を残して、どれを削るか」「どう組み直すか」を毎回考える必要があります。\n\n地味に大変だからこそ、ここをAIに任せられたら嬉しいと思っていました。そんな中、Adobe の Illustrator MCP （AIから Illustrator を操作できる仕組み）を試せるようになりました。\n\nそこで社内勉強会のテーマとして、 同じマスターバナーから3サイズを手作業とAIでそれぞれ作り、時間と仕上がりを比べてみました。この記事では、検証の条件、結果、AIに任せられたこと・人の判断が必要だったことをまとめます。\n\nうまくいかなかったこともそのまま書いています。2.","importance":5},{"title":"ページ内リンクの見出しが固定ヘッダーに隠れるので、scroll-padding-topとヘッダー高さの変数で直す","url":"https://zenn.dev/nadarakainc/articles/55671503799398","source":"Zenn","published_at":"2026-11-24 09:42","genre":"web","genre_label":"Web開発・言語","headline":"コーポレートサイトで「よくある質問」や「アクセス」へのページ内リンクを置くと、次のような報告を受けることがあります。","summary":"コーポレートサイトで「よくある質問」や「アクセス」へのページ内リンクを置くと、次のような報告を受けることがあります。ヘッダーを position: sticky （または fixed ）で画面上部に固定していると、ブラウザーはリンク先の見出しをビューポートの一番上へスクロールします。\n\nその一番上には固定ヘッダーが重なっているため、見出しがちょうどヘッダーの裏に入ります。古い対処として、見出しの前に空の要素を置いて負のマージンでずらす方法や、JavaScriptでクリックを横取りして window.scrollTo() で位置を計算する方法があります。\n\nいまはCSSの scroll-padding-top を1行足すだけで、多くのケースが直ります。ただし、1行で終わらないところが2つありました。\n\nヘッダーの高さがブレークポイントやお知らせ帯で変わると、固定値のずれがそのまま残る scroll-margin-top を見出しにだけ付けると、キーボード操作でフォーカスしたリンクがヘッダーの裏に残る この記事では、次の順に確認します。","importance":5},{"title":"\"CPUマシン47台をPXEブートでつないで、Slurmクラスタを一から作った：構築手順とハマったこと全部\"","url":"https://zenn.dev/gohantec/articles/6ac740572c7d16","source":"Zenn","published_at":"2026-11-23 22:04","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"卒業研究のために、 CPUマシン47台と管理用のマシン1台をラックに並べて配線し、計算クラスタを一から組みました 。","summary":"卒業研究のために、 CPUマシン47台と管理用のマシン1台をラックに並べて配線し、計算クラスタを一から組みました 。ジョブスケジューラには Slurm を入れています。\n\n計算ノードにはディスクを付けず、OSは PXEブート でネットワーク越しに読み込みます（ルートファイルシステムは NFS）。この形は、ノードごとにOSを入れなくてよいので管理は楽です。\n\nその代わり、台数が増えると ディスクのあるクラスタでは起きない問題 がいくつも出てきました。この記事では、構築の流れを短くまとめます。\n\nそのあと、 実際に出たエラーと直し方 を「症状 → 原因 → 対処」の形で並べます。同じ構成で作る人のトラブルシューティング集として使ってもらえるとうれしいです。\n\nできあがったクラスタでの Slurm のコマンドの使い方は、別の記事「自作した47台のCPUクラスタでSlurmを使う」にまとめています。管理ノード（head）1台が、次の仕事を全部受け持っています。\n\n計算ノードはラックに段ごとに積んであります。1.","importance":5},{"title":"変なTinyLMを12匹育てたら、自作GPTの組み合わせが条件つきでQwen2.5-0.5Bを上回った話","url":"https://zenn.dev/emilia_lab/articles/tiny-lm-12-vs-llm","source":"Zenn","published_at":"2026-11-24 15:36","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"「睡眠」「忘却」「量子トンネル」「伝染」「砂山」……そんな ちょっと変な仕組みで動く小さな言語モデル（TinyLM）を12匹 、思いつ…","summary":"「睡眠」「忘却」「量子トンネル」「伝染」「砂山」……そんな ちょっと変な仕組みで動く小さな言語モデル（TinyLM）を12匹 、思いつきで作っていました。動くことは動く。\n\nでも「で、どれくらい言語モデルとして育つの？」が分からない。そこで今回は、12匹全員に 本物の文章を読ませて育て 、LLM と同じ物差しで「どこまで登れるか」を測りました。\n\n最後は、自作の文字単位 GPT の組み合わせが、事前学習済み LLM の Qwen2.5-0.5B（5億パラメータ）より bits/char を下げる（＝予測成績で上回る） ところまで、 ある評価条件の下で 行きました。その「条件」も含めて書きます。\n\nコードと結果は GitHub に置いてあります（MIT）: https://github.com/kagioneko/tiny-lm-growth 物差し: まだ読んでいない文章の bits/char 比べ方はひとつだけです。","importance":5},{"title":"品質を積み上げられるようにする","url":"https://speakerdeck.com/goyoki/building-up-of-quality","source":"Hatena","published_at":"2026-11-24 08:53","genre":"web","genre_label":"Web開発・言語","headline":"コンポーネント品質の積み上げの恩恵： 高度な品質実現をサポートする 品質 レベル 平常 状態 その時の開発力に依存 鍛えれば品質が高ま…","summary":"Hiroki Iseri 品質を積み上げられるようにする QA Test Talk Vol.9 2026/11/24 井芹 洋輝 品質を積み上げられるようにする QA Test Talk Vol.9 2026/11/24 井芹 洋輝 自己紹介 ⚫@goyoki ⚫車メーカーのQA/テストテックリード、QMアーキテクト ⚫最近執筆した書籍 → 本テーマの詳細を書いています 買っていただけると嬉しいです 2 自己紹介 ⚫@goyoki ⚫車メーカーのQA/テストテックリード、QMアーキテクト ⚫最近執筆した書籍 → 本テーマの詳細を書いています 買っていただけると嬉しいです 2 品質の積み上げ ⚫品質エンジニアリングの工夫で、積み上げるように品質を確保・改善でき るようになる ⚫この「品質の積み上げ」はさまざまな恩恵を提供する ⚫品質の積み上げの種類 • 工程品質の積み上げ • 従来の「品質の積み上げ」。\n\n自工程完結とも • 工程ごとに品質の責務を果たす。","importance":5},{"title":"マクドナルド公式アプリのデータベースへの不正アクセスに関するお知らせとお詫び | マクドナルド公式","url":"https://www.mcdonalds.co.jp/company/info/261120a/","source":"Hatena","published_at":"2026-11-21 18:09","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"平素より日本マクドナルド公式アプリをご利用いただき、誠にありがとうございます。","summary":"平素より日本マクドナルド公式アプリをご利用いただき、誠にありがとうございます。このたび、当社が管理するマクドナルド公式アプリのデータベース内のお客様に関連する情報の一部に対して第三者による不正アクセスが確認されました。\n\n詳細は下記の通りです。なお、本件に起因する公式アプリ・サービスの不正利用は確認されておりません。\n\nお客様にご心配をお掛けしておりますことを、深くお詫び申し上げます。不正アクセスの対象となった情報 ・システム上の顧客管理用ID ※ ※単体ではお客様情報が識別できないIDとなり、日本マクドナルド公式アプリの会員IDや、お客様のメールアドレスとは異なります。\n\n・サービスご提供時に利用した携帯端末の位置情報 なお公式アプリにご登録いただいているお客様の氏名、メールアドレス、電話番号、住所、クレジットカード情報などは含まれません。現時点で、お客様にパスワードの変更などの特別なお手続きをお願いするものではございません。","importance":5},{"title":"ISUCON2026 問題解説と講評 : ISUCON公式Blog","url":"https://isucon.net/archives/isucon2026-problem-review.html","source":"Hatena","published_at":"2026-11-24 15:16","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"こんにちは、ISUCON2026作問チーム「第n西東京市」のwhywaitaです。","summary":"こんにちは、ISUCON2026作問チーム「第n西東京市」の whywaita です。この記事では、ISUCON2026問題「写真共有SNS ISUReal」についての問題解説と講評についてお届けさせていただきます。\n\n今回の作問は、ISUCON6から同じチームを組んできた 第n西東京市のメンバー（whywaita, nomeaning, icchy）と、アドバイザーとして fujiwara さんに参加いただきました。ISUCON2026 の問題は、日常の写真を友達と共有する SNS「ISUReal」でした。\n\n当日公開した問題動画がYouTubeにアップロード済みですので、こちらを見ていただければぐっと解像度が上がると思います。利用者は asia、europe、america の3地域に分かれ、各地域で投稿期間が開くと通知を受け取り、自分の写真を投稿してから友達の写真を閲覧します。","importance":5},{"title":"JSConf JP 2026に参加記録・初登壇の反省など","url":"https://zenn.dev/igrep/articles/2026-11-jsconfjp","source":"Zenn","published_at":"2026-11-24 00:08","genre":"web","genre_label":"Web開発・言語","headline":"去る2026年11月22日、に開催された JSConf JP 2026 に参加し、初めて登壇させていただくことができました🎉！","summary":"去る2026年11月22日、に開催された JSConf JP 2026 に参加し、初めて登壇させていただくことができました🎉！この記事では私の発表内容や反省、そして他の方々の発表で印象に残ったものなどをまとめます。\n\nJS･WasmにもあるRustのアレ - コンポーネント間でやりとりするオブジェクトを管理する (1) Wasm Component Model について、「Rust 好きな人が Wasm を無駄に複雑にしてしまった」みたいな批判をちらほらと見かけたことが作ろうと思ったきっかけです。\n\nこういう、Rust を使わないで所有権を説明した資料が必要なんじゃないかと考えたのです。批判していた方々の主張をつぶさに読んだわけではないし、他にも論点はあるでしょうから直接取り上げはしませんでしたが、まあいずれにしても、「所有権」という概念も Wasm Component Model も Rust だけのものではありませんので、 postMessage という、比較的身近な例を通じてみなさんが所有権に触れるきっかけになれば幸いです。","importance":5},{"title":"Lean で始める契約プログラミング - エムスリーテックブログ","url":"https://www.m3tech.blog/entry/contract-programming-in-lean","source":"Hatena","published_at":"2026-11-24 14:30","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"こんにちは。","summary":"こんにちは。Unit3 / 基盤開発チームを兼務している林です。\n\nUnit3では、主に医学書の電子書籍サービスや、医師の開業サポートなどのサービスを担当しています。今回は Unit3 テックブログリレー 1 日目の記事です。\n\nLean で証明付きの安全な開発をするイメージを Gemini で生成しました 定理証明ができるプログラミング言語、Lean Lean というプログラミング言語をご存知でしょうか？このところ AI で Lean を使って数学などですごい成果が続々と発表されていて、つい先日も Claude を使ってリーマン予想を Lean により証明できたとの発表 （ Lean コミュニティによる検証の声明 ）がありました。\n\nLean の名前を聞いたことがある方も多いのではないでしょうか。数学の定理を証明できる言語となると、普段使っているプログラミング言語とはまったく異なるパラダイムのもの、と感じるかもしれませんが、実は Lean はプログラミング言語の1つであり、普通にプログラムを書けます。","importance":5},{"title":"0.3秒で答えるAIは、暗算でつまずく ― Jev・OpenAI・Geminiの判断APIを165問で比べた","url":"https://zenn.dev/rehabforjapan/articles/decision-api-comparison","source":"Zenn","published_at":"2026-11-24 14:01","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"Rehab for JAPANでCTOを務めている @rkyuragi です。","summary":"Rehab for JAPANでCTOを務めている @rkyuragi です。2026年11月にGoogleのGemini Decisions APIが公開され、TypeSafeのJev、OpenAIのDecisions APIと合わせて、判断専用のAPIが3社からそろいました。\n\nどれも文章を生成せず、質問ごとに確率付きの答えを0.15〜0.3秒ほどで返します。以前、Jevの「確率で答える」という出力の形について 記事 を書きました。\n\nあのときは眺めて考えただけだったので、今回は実際に測っています。私たちのサービスには、介護記録や問い合わせを読んで振り分けたり、決まりに当てはまるかを判定したりする場面がたくさんあります。\n\n判断APIを使うかどうかはまだ決めていませんが、こうした場面でどこまで通用するのかを技術検証として確かめるため、同じ問題を3つに解かせて比べてみました。比べる作業は、問題と想定の正解を書くところから、APIを呼んで採点し、統計で確かめ、結果を考察するところまで、ほとんどClaude Codeに任せました。","importance":5},{"title":"研究用のコードを、Claude Codeに任せてプロダクトにした","url":"https://zenn.dev/simulacra/articles/746128265d748c","source":"Zenn","published_at":"2026-11-24 12:00","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"Simulacraは、論文や社内の研究開発をもとにプロダクトを作っています。","summary":"Simulacraは、論文や社内の研究開発をもとにプロダクトを作っています。AIインタビューサービス「うつしみ」もその1つです（ 製品紹介 ）。\n\n複数のAIエージェントが協調して回答者と対話し、事前に想定していなかった論点も深掘りしながら、その人の経験や考え方、普段は言葉にしていない判断基準を引き出します。うつしみのインタビューのロジックは、2026年1月から1年近く、社内で研究開発してきたものです。\n\nそのプロトタイプを土台に、開発の大半をClaude Codeに任せる形で、10日ほどでプロダクトとして運用できる品質に作り直しました。少人数で開発を進めるために、設計・実装・レビューをLLMに任せ、人は判断に集中する仕組みを組みました。\n\nうつしみは企業からの依頼ごとに導入していて、聞きたいことや設定が導入先によって異なります。プロトタイプは試験運用まで進んでいましたが、導入先ごとに設定を差し替えて配布し、継続的に運用するには向いていませんでした。\n\n特にインタビューのロジックが複雑で、少人数で保守し続けるには負担が大きい状態でした。","importance":5},{"title":"Microsoft Foundry で AI エージェントを設計するときに決める5つのこと","url":"https://zenn.dev/microsoft/articles/daedf42c8463b8","source":"Zenn","published_at":"2026-11-24 11:59","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"Microsoft Foundry で AI エージェントを作るときは、データの保存先やエージェントの作成方式、接続するツールを選び、…","summary":"Microsoft Foundry で AI エージェントを作るときは、データの保存先やエージェントの作成方式、接続するツールを選び、利用に必要な権限やネットワークも設計します。本記事では、それぞれの選択がどう関わり合うのかを理解し、エージェント設計の全体像をつかめるように、図中の 1 〜 5 に沿って整理していきます。\n\n1. 会話履歴やファイルをどこに保存するのか Microsoft Foundry では、Foundry リソースの下にプロジェクトを作り、その中にエージェントを作成します。Agent Service が管理するデータを共有する単位は、プロジェクトです。\n\n同じプロジェクトに複数のエージェントを作ると、ファイルや会話履歴の保存先、検索インデックスを共有します。これらのデータを分離したい場合は、プロジェクトを分けます。\n\nこのプロジェクトの保存基盤を誰が用意し、管理するかを決めるのが、Basic agent setup と Standard agent setup です。","importance":5},{"title":"ちょっと待って！そのSkills本当に必要？―skillなしと比べて指示を削る","url":"https://zenn.dev/green_tea/articles/5eea2714ba1db2","source":"Zenn","published_at":"2026-11-24 11:45","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"みなさん、skills 作ってますか？","summary":"みなさん、skills 作ってますか？そして、メンテナンスしてますか？\n\nClaude Code の生みの親 Boris Cherny 氏は YouTube で以下のような発言をしています。For people who aren’t building agentic products but are using Claude Code, every 6 months, delete your CLAUDE.md file, delete your skills, and delete your hooks.\n\nThen see what the model does.It might surprise you. 私なりに訳すと、エージェントを開発しているわけではない普通の Claude Code を使っている人は、6ヶ月ごとに CLAUDE.md、skills, hooks を削除しましょう。\n\nその後、モデルがどう動くか見て驚け！といった感じです。\n\nさらに以下のようにも語っています。","importance":5},{"title":"RTX 5070 Ti 16GB で動くローカル LLM を 8 種類比べて、Claude から任せられそうな仕事とモデルを探った話","url":"https://zenn.dev/hikari_lab_dev/articles/ef4a3fe94b3b2f","source":"Zenn","published_at":"2026-11-24 11:38","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"手元の GPU で動くローカル LLM 8 種類と Claude を、3 つの課題で比べました。","summary":"手元の GPU で動くローカル LLM 8 種類と Claude を、3 つの課題で比べました。思ったほどの性能は出ませんでしたが、次の範囲なら任せられそうだと分かりました。\n\n仕様と合否の条件が決まったコードの実装は、Qwen3.8-27B に任せられそう 照合や抜き出しのような手順の決まった事務作業は、Gemma 4 26B-A4B に任せられそう 公開情報の Web 調査は、Qwen3.8-27B に任せられそう 設計と合否の判断、小さな修正は、クラウドの Claude に残す 避けるのは、Sonnet がローカルに仕様書を渡す組み合わせです。\n\n用途ごとの任せる先は、後半の章で図と表にまとめました。ローカル LLM にどこまで任せられるか 私は開発も事務作業も Claude Code で回しています。\n\n手元の PC には RTX 5070 Ti（VRAM 16GB）があります。そこで、手元のローカル LLM に、仕事をどこまで任せられるかを検討しました。\n\n結果として、思ったほどの性能は出ませんでした。","importance":5},{"title":"ずんだもん、公式の画像生成AI用「LoRA」を公開　権利元が語る“絵師に迷惑をかけない”試み","url":"https://kai-you.net/article/97231","source":"Hatena","published_at":"2026-11-24 11:35","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"AI創作プラットフォーム「PixAI」が、ずんだもんなど4キャラクターに対応した公式コラボLoRA「ずん子・ずんだもん達」を公開した。","summary":"AI創作プラットフォーム「PixAI」が、ずんだもんなど4キャラクターに対応した公式コラボLoRA「ずん子・ずんだもん達」を公開した。東北ずん子・ずんだもんプロジェクトから公式素材の提供を受けて制作し、権利元による公式監修を経たAIプロジェクトとなる。\n\n画像や映像、音声をつくるハードルは急速に下がり、専門的な技術を持たない人でも、アイデアを短時間で形にできるようになった。","importance":5},{"title":"Claude Code を5〜8個並べても迷わないように、自分用のダッシュボードをバイブコーディングで作った","url":"https://zenn.dev/nexta_/articles/a3ff76a9f98f1c","source":"Zenn","published_at":"2026-11-24 11:30","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"Claude Code は、VSCode の拡張機能で使うのが好きだ。","summary":"Claude Code は、VSCode の拡張機能で使うのが好きだ。Markdown が見やすく、コードも Git の変更差分もその場で見られる。\n\nパネルを横に並べられるので、セッション同士が隠れない。VSCode から離れずに済む。\n\nただ、セッションを5つほど並べると困ることが出てくる。一番困ったのは、パネルの見出しが短くて、どれが何の作業をしているのか一目で分からないことだった。\n\n一時期はメモ帳にパネルの並び順と同じ順で、それぞれ何をしているかを書いていた。困りごとはほかにもあった。\n\nどれが自分の返事を待っているのか、パネルを1つずつ見て回らないと分からない Slack を読んでいると、返事待ちになったことに気付けない 決めた手順（スキル）どおりに Claude が動いているのか分からない タブを閉じてよいのか迷う 前にやった作業を探せない 決まった作業や期日のある作業を忘れる 使用枠があとどれくらい持つのか分からない そこで、セッションの様子を1枚で見られるダッシュボードを、バイブコーディングで自分用に作った。","importance":5},{"title":"「光ったら検知」がなぜ難しい？ 現場で磨いた画像処理アルゴリズム","url":"https://zenn.dev/safie_inc/articles/3875638ad636cd","source":"Zenn","published_at":"2026-11-24 11:00","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"「カメラでライトを映して、光ったら検知する。」 言葉にすると簡単そうですが、実際に現場の映像で試すと、想定外の問題が次々と見つかり苦労…","summary":"「カメラでライトを映して、光ったら検知する。」 言葉にすると簡単そうですが、実際に現場の映像で試すと、想定外の問題が次々と見つかり苦労しました。難しさの中心は、現場ごとにライトの見え方が変わるため、同じ基準では点灯を判定できないことでした。\n\nこんにちは。セーフィーの AI 開発部で AI アプリの開発に携わっている木村です。\n\n今回は、カメラの映像から設備の稼働状況を把握する「AI-App 設備ウォッチャー」（以下、設備ウォッチャー）の開発を題材に、ライトの点灯を検知するアルゴリズムを、現場でどう見直し、改善したかを紹介します。設備の稼働状況を、ライトから知る 製造現場では、設備の停止による稼働率の低下が生産計画に影響するため、設備の安定稼働が課題となっています。\n\n停止や異常の再発防止や初動対応の改善につなげるには、停止時に何が起きていたかを振り返る必要があります。しかし、古い設備などでは稼働データを直接取得できず、ストップウォッチや紙で記録しているため、後から調べるのも簡単ではありません。","importance":5},{"title":"要件定義書のレビュー観点を、チェックリストにしてみた","url":"https://zenn.dev/vaonvn/articles/395e38023ae063","source":"Zenn","published_at":"2026-11-24 09:59","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"この半年、要件定義書とLLMについて何本か書いてきました。","summary":"この半年、要件定義書とLLMについて何本か書いてきました。初稿をLLMに書かせた話、AIコードレビューの指摘を記録した話、初稿のプロンプトをコードと一緒に管理した話、設計レビューをLLMにどこまで任せるか決め直した話、ドキュメントの鮮度を数えた話です。\n\n書き終えて読み返すと、要件定義書をレビューするときに見るべきことが、記事のあちこちに一つずつ散らばっていました。そこで今回は、それを一枚のチェックリストにしました。\n\n過去の記事のまとめではなく、次の要件定義書のレビューでそのまま使うための道具として作っています。後半に、機械で確かめられる部分を見る小さなスクリプトと、コピーして使える版を載せました。\n\n観点を「根拠がどこにあるか」で分けた チェックリストを作るとき、最初は「機能」「非機能」「用語」のように、要件定義書の章に沿って並べようとしました。ただ、それだと一つの章の中に、数秒で確かめられる項目と、ヒアリングに出た人でないと判断できない項目が混ざります。","importance":5},{"title":"Museに後れを取るアップルとグーグル　AIエージェント戦争のジレンマ【西田宗千佳のイマトミライ】","url":"https://www.watch.impress.co.jp/docs/series/nishida/2158551.html","source":"Hatena","published_at":"2026-11-24 09:16","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"西田宗千佳のイマトミライ 2026年11月24日 08:20 Metaの「Muse」をはじめとした、パーソナルAIエージェントの勢いが…","summary":"西田宗千佳のイマトミライ 2026年11月24日 08:20 Metaの「Muse」をはじめとした、パーソナルAIエージェントの勢いが止まらない。パーソナルAIエージェントはPCの上で使っても便利なものだが、やはりスマートフォンで使い、生活の中に入れてこそ本質が発揮されるものだ。\n\n安全性などに不安を感じる人はいるだろう。ただ同時に、こうしたサービスが急速に認知を高め、支持を得ていること自体は否定できない。\n\nだとすると、ここで気になってくるのは「スマートフォンプラットフォーマーはどのように立ち回るのか」という点だ。スマートフォンの2大プラットフォーマーであるアップルもGoogleも現状は、パーソナルAIエージェントの部分において先進的な手を打てていない。\n\nでは現状、どのような機能が実装されているのだろうか。各社の状況をまとめ、今後どうなるかを考えてみよう。\n\nアプリストアで1位を続けるMuseの勢い 常時駆動型でパーソナルなAIエージェントの中でも、MetaのMuseは特に勢いがすごい。アメリカでスタートしたのが今年の9月8日。","importance":5},{"title":"内部のAIと外部のAI ― Museを中心に、Codex・Claude Code・Suno・Colabまでを束ねる配置の話","url":"https://zenn.dev/nariyuki_pdm/articles/9604db4966e6e5","source":"Zenn","published_at":"2026-11-24 08:58","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"第1弾では、Museの下にVM内エージェントとMac内エージェントを2段ぶら下げ、開発作業を振り分ける「3層×3経路」の構成を書いた（…","summary":"第1弾では、Museの下にVM内エージェントとMac内エージェントを2段ぶら下げ、開発作業を振り分ける「3層×3経路」の構成を書いた（第1弾： https://zenn.dev/nariyuki_pdm/articles/e83fbbbc1ca619 ）。あれは開発の委任をどう深くするか、という範囲内の話だった。\n\n層と経路の話は、その範囲の中での縦と横である。実際に運用していると、配置の対象は開発の外側にも広がる。\n\n文案を比べるために同じ層に複数のAIを並べる。作曲や音声合成のように、自分の環境の外にある生成サービスを呼ぶ。\n\nGPUが要る作業は、計算資源ごと外に出す。本記事は、その広がりまで含めた配置の話である。\n\nここで最初に、言葉の定義を固定しておく。本記事で「内部／外部」を分ける軸は、 実行場所ではなく、統制の所在 である。\n\n第1層が台帳・検収・承認を持つ範囲を「内部」、統制の外にある生成サービスを「外部」と呼ぶ。実行そのものは、内部のエージェントであっても実際にはクラウド側のモデルが担っていることが多い。","importance":5}]};
